function createTimer(durationMs, onTick) {
  let remaining = durationMs;
  let startedAt = null;
  let timerId = null;

  function start() {
    startedAt = Date.now();
    timerId = setTimeout(() => {
      remaining = 0;
      onTick(0);
    }, remaining);
  }

  function pause() {
    clearTimeout(timerId);
    remaining -= Date.now() - startedAt;
  }

  return { start, pause };
}

